}

::deep .btn-page {
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    text-align: center;
    padding: 3rem 1rem;
    color: #6c757d;
}

.catalog-error {
    color: #dc3545;
}

.catalog-error button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

